def make_wechat():
    wb = Workbook()
    ws = wb.active
    ws.title = "Sheet1"
    for row in WECHAT_HEADER_ROWS + [WECHAT_COLUMNS] + WECHAT_ROWS:
        ws.append(row)
    path = HERE / "wechat_sample.xlsx"
    wb.save(path)
    return path


if __name__ == "__main__":
    print("已生成：", make_alipay())
    print("已生成：", make_wechat())
